#include <iostream>

int main() {
    bool isComplete = true;
    int number = 1000;
    double value = 0.0947628;

    // 1. Default boolean and numeric output
    std::cout << "Default bool: " << isComplete << "\n";

    // 2. Enable boolalpha
    std::cout << "With boolalpha: " << std::boolalpha << isComplete << "\n";

    // 3. Save original format flags
    std::ios_base::fmtflags originalFormat = std::cout.flags();

    // 4. Modify multiple formatting flags
    std::cout << std::showbase << std::oct << std::scientific;
    std::cout << "Modified format:\n";
    std::cout << "Octal int: " << number << "\n";
    std::cout << "Scientific double: " << value << "\n";

    // 5. Restore original format flags
    std::cout.flags(originalFormat);
    std::cout << "Restored format:\n";
    std::cout << "Decimal int: " << number << "\n";
    std::cout << "Normal double: " << value << "\n";

    // 6. Reset boolalpha with noboolalpha
    std::cout << std::noboolalpha;
    std::cout << "Reset bool: " << isComplete << "\n";

    return 0;
}

#include <iostream>
#include <sstream>
#include <string>

int main() {
    // Input contains an invalid token, a valid integer, and remaining text
    std::istringstream input("abc 42 remaining");
    int value = 0;

    std::cout << "Initial state: good=" << input.good() 
              << " fail=" << input.fail() << "\n";

    // Attempt extraction which fails because 'abc' is not an integer
    input >> value;
    std::cout << "After failed extraction: good=" << input.good()
              << " fail=" << input.fail() << "\n";

    // Clear the error state
    input.clear();
    std::cout << "After clear(): good=" << input.good()
              << " fail=" << input.fail() << "\n";

    // Discard the unread invalid token and read the integer
    std::string garbage;
    input >> garbage;
    input >> value;

    std::cout << "Discarded token: " << garbage << "\n";
    std::cout << "Successfully read integer: " << value << "\n";
    std::cout << "State before EOF: good=" << input.good() << "\n";

    return 0;
}
